import sys

def partition_brute(S):
    n = len(S)
    res = []
    i = 0
    while i < n:
        seen = set()
        j = i
        while j < n:
            seen.add(S[j])
            end = max(S.rfind(c) for c in seen)
            if end == j:
                res.append(end - i + 1)
                i = end + 1
                break
            j += 1
    return res

if __name__ == '__main__':
    S = sys.stdin.readline().strip()
    for x in partition_brute(S):
        print(x)

import sys

def partition_opt(S):
    n = len(S)
    last = {c: i for i, c in enumerate(S)}
    res = []
    end = start = 0
    for i, c in enumerate(S):
        end = max(end, last[c])
        if i == end:
            res.append(end - start + 1)
            start = end + 1
    return res

if __name__ == '__main__':
    S = sys.stdin.readline().strip()
    for x in partition_opt(S):
        print(x)

import sys

def partition_best(S):
    last = {c: i for i, c in enumerate(S)}
    res = []
    e = b = 0
    for i, c in enumerate(S):
        e = max(e, last[c])
        if i == e:
            res.append(e - b + 1)
            b = e + 1
    return res

if __name__ == '__main__':
    S = sys.stdin.readline().strip()
    for x in partition_best(S):
        print(x)
